  "outcome": "deny",
  "rationale": "We deny this claim because the claimant's account states that she deliberately steered her car into a concrete bollard on purpose, meaning the loss was not accidental. This falls outside of the collision coverage insuring agreement which requires an accidental loss. Therefore, the loss is not covered.",
  "citations": [
    {
      "clause_id": "PLUS-2.1",
      "quote": "we will pay for direct and accidental loss to the covered vehicle caused by collision during the policy period."
    }
  ]
}
